widget.solution:
def payoff(legs, S):
    """Total payoff at expiry of a list of (kind, qty, strike) legs."""
    total = 0.0
    for kind, qty, strike in legs:
        if kind == "call":
            total += qty * max(S - strike, 0)
        elif kind == "put":
            total += qty * max(strike - S, 0)
        elif kind == "stock":
            total += qty * S
    return total


def table(legs, prices):
    return [payoff(legs, S) for S in prices]
